RECORD = {
    "id": "JAH-NMP5-000001",
    "name": "Jan",
    "kind": "first-name",
    "meaning": "Jan is a masculine given name in Polish. Meaning: God is gracious. The Polish form of John."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Jan")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

